class ErrorCode(enum.Enum):
    """
    A stable numeric error code. The discriminant is the number; see
    `arachne_api::ErrorCode` for the ranges and rules.
"""
    
    CLOSED = 1
    
    CANCELLED = 2
    
    DEADLINE_EXCEEDED = 3
    
    INVALID_INPUT = 100
    
    INVALID_ID = 101
    
    WRONG_STATE = 102
    
    UNSUPPORTED = 103
    
    CAPACITY_EXCEEDED = 200
    
    LIMIT_REACHED = 201
    
    STORAGE_FAILED = 300
    
    STORAGE_CORRUPT = 301
    
    CANDIDATE_STALE = 302
    
    PEER_UNREACHABLE = 400
    
    TIMEOUT = 401
    
    TRANSPORT_FAILED = 402
    
    NOT_AUTHORIZED = 500
    
    INVITATION_INVALID = 501
    
    INVITATION_EXPIRED = 502
    
    NOT_MEMBER = 503
    
    EPOCH_MISMATCH = 600
    
    POLICY_MISMATCH = 601
    
    INTERNAL = 900
    
    def number(self, ) -> int:
        """
        The stable number of this code.
"""
        _uniffi_lowered_args = (
            _UniffiFfiConverterTypeErrorCode.lower(self),
        )
        _uniffi_lift_return = _UniffiFfiConverterUInt32.lift
        _uniffi_error_converter = None
        _uniffi_ffi_result = _uniffi_rust_call_with_error(
            _uniffi_error_converter,
            _UniffiLib.uniffi_arachne_sdk_fn_method_errorcode_number,
            *_uniffi_lowered_args,
        )
        return _uniffi_lift_return(_uniffi_ffi_result)


