# ApiError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class ApiError(Exception):
    """
    The error of every SDK call. Programs read `api_error_code(error)`; the
    text is for people and never holds secrets.
"""
    pass

_UniffiTempApiError = ApiError

class ApiError:  # type: ignore
    """
    The error of every SDK call. Programs read `api_error_code(error)`; the
    text is for people and never holds secrets.
"""
    
    class Closed(_UniffiTempApiError):
        
        def __init__(self):
            pass

        def __repr__(self):
            return "ApiError.Closed({})".format(str(self))
    _UniffiTempApiError.Closed = Closed # type: ignore
